import{_ as a,o as n,a as p,b as c}from"./app.UgfkfLuP.js";const o=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"HCCL通信类","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_communication"},{"text":"HCCL MC2接口","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_MC2/HCCL_MC2"},{"text":"CheckOpResSufficient","link":"/api/SIMD-API/adv_api/HCCL_communication/HCCL_MC2/CheckOpResSufficient"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_MC2/CheckOpResSufficient.md","filePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_MC2/CheckOpResSufficient.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1790582767000}'),l={name:"api/SIMD-API/adv_api/HCCL_communication/HCCL_MC2/CheckOpResSufficient.md"};function t(e,s,i,d,C,r){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>CheckOpResSufficient</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>根据MC2通信参数，对指定通信算法所需的CCU通信资源进行预校验。该接口只做资源探测，不返回通信资源上下文，也不启动通信服务端。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="n">HcclResult</span><span class="w"> </span><span class="n">__attribute__</span><span class="p">((</span><span class="n">visibility</span><span class="p">(</span><span class="s">&quot;default&quot;</span><span class="p">)))</span><span class="w"> </span><span class="n">CheckOpResSufficient</span><span class="p">(</span>
<span class="w">    </span><span class="n">HcclComm</span><span class="w"> </span><span class="n">comm</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">ccType</span><span class="p">,</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">ccArgs</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>comm</td><td>输入</td><td>已初始化的通信域句柄。</td></tr><tr><td>ccType</td><td>输入</td><td>通信任务类型，取值为HcclCMDType枚举值，当前支持AllGather、AllReduce、ReduceScatter、AlltoAll和AlltoAllV。</td></tr><tr><td>ccArgs</td><td>输入</td><td><a href="Mc2GetCcArgs.html">Mc2GetCcArgs</a>创建并通过Mc2SetCc*接口填充的MC2通信参数对象。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回HcclResult类型的值，具体取值参考下表。</p><p><strong>表2</strong> 返回值说明</p><table><thead><tr><th>返回值</th><th>描述</th></tr></thead><tbody><tr><td>HCCL_SUCCESS</td><td>资源充足，或当前场景不执行真实资源探测。</td></tr><tr><td>HCCL_E_PARA</td><td>参数格式非法。</td></tr><tr><td>HCCL_E_PTR</td><td>空指针错误。</td></tr><tr><td>HCCL_E_NOT_SUPPORT</td><td>设备、通信任务或通信引擎不支持。</td></tr><tr><td>HCCL_E_ALG_NOT_SUPPORTED</td><td>算法未注册。</td></tr><tr><td>HCCL_E_RES_NOT_SUFFICIENT</td><td>所需通信资源不足。</td></tr></tbody></table><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>ccArgs必须由<a href="Mc2GetCcArgs.html">Mc2GetCcArgs</a>创建。</li><li>仅当通信域rank数大于1且通信引擎为CCU_SCHED时执行真实资源探测；其他场景直接返回HCCL_SUCCESS。</li><li>AICPU_TS和CCU_MS路径当前不执行真实资源探测。</li><li>本接口不替代<a href="Mc2AcquireCcResCtx.html">Mc2AcquireCcResCtx</a>，资源预检查通过后仍需正式申请通信资源上下文。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">ccType</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HcclCMDType</span><span class="o">::</span><span class="n">HCCL_CMD_ALLTOALL</span><span class="p">);</span>

<span class="n">HcclResult</span><span class="w"> </span><span class="n">checkRet</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CheckOpResSufficient</span><span class="p">(</span><span class="n">comm</span><span class="p">,</span><span class="w"> </span><span class="n">ccType</span><span class="p">,</span><span class="w"> </span><span class="n">ccArgs</span><span class="p">);</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">checkRet</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">HCCL_E_RES_NOT_SUFFICIENT</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="c1">// 资源不足处理，例如回退到其他通信路径或提示用户</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">checkRet</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="n">HCCL_SUCCESS</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="c1">// 参数或内部异常处理</span>
<span class="p">}</span>

<span class="n">Mc2Result</span><span class="w"> </span><span class="n">acquireRet</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">Mc2AcquireCcResCtx</span><span class="p">(</span><span class="n">comm</span><span class="p">,</span><span class="w"> </span><span class="n">ccType</span><span class="p">,</span><span class="w"> </span><span class="n">ccArgs</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">ccResCtx</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">ccResCtxSize</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const _=a(l,[["render",t]]);export{o as __pageData,_ as default};
